// === Tab: mySketch ===
// OpenProcessing sketch – p5.js + WEBGL
// Combines Inigo Quilez’s fbm “warp” field with an iridescent metaball shader
// ---------------------------------------------------------------------------

let myShader;

const vertSource = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 pos = vec4(aPosition, 1.0);
  pos.xy = pos.xy * 2.0 - 1.0;   // full-screen quad
  gl_Position = pos;
}
`;

//  ┌──────────────────────────────────────────────────────────────────────┐
//  │  Fragment shader – GPL-like educational license by Inigo Quilez     │
//  │  Portions © Iñigo Quílez / iq (2013). See https://iquilezles.org    │
//  │  May be used for educational purposes only, with attribution.       │
//  └──────────────────────────────────────────────────────────────────────┘
const fragSource = `
#ifdef GL_ES
precision mediump float;
#endif

varying vec2 vTexCoord;
uniform float u_time;
uniform vec2  u_resolution;

// ------------------------------------------------------------------
// Map Shadertoy globals → p5.js uniforms so we can leave iq’s code as-is
#define iTime        u_time
#define iResolution  vec3(u_resolution, 1.0)

// ---------------- Inigo Quilez fbm helper functions ----------------
float hash(vec2 p){
    p = fract(p*0.6180339887);
    p *= 12.0;
    return fract(p.x*p.y*(p.x+p.y));
}
float noise(vec2 x){
    vec2 p = floor(x);
    vec2 f = fract(x);
    f = f*f*(3.0-2.0*f);
    float a = hash(p);
    float b = hash(p+vec2(1.0,0.0));
    float c = hash(p+vec2(0.0,1.0));
    float d = hash(p+vec2(1.0,1.0));
    return mix(mix(a,b,f.x), mix(c,d,f.x), f.y);
}
const mat2 mtx = mat2( 0.80,  0.60, -0.60,  0.80 );
float fbm4(vec2 p){
    float f = 0.0;
    f += 0.5000*(-1.0+2.0*noise(p)); p = mtx*p*2.02;
    f += 0.2500*(-1.0+2.0*noise(p)); p = mtx*p*2.03;
    f += 0.1250*(-1.0+2.0*noise(p)); p = mtx*p*2.01;
    f += 0.0625*(-1.0+2.0*noise(p));
    return f/0.9375;
}
float fbm6(vec2 p){
    float f = 0.0;
    f += 0.500000*noise(p); p = mtx*p*2.02;
    f += 0.250000*noise(p); p = mtx*p*2.03;
    f += 0.125000*noise(p); p = mtx*p*2.01;
    f += 0.062500*noise(p); p = mtx*p*2.04;
    f += 0.031250*noise(p); p = mtx*p*2.01;
    f += 0.015625*noise(p);
    return f/0.96875;
}
vec2 fbm4_2(vec2 p){ return vec2( fbm4(p+vec2(1.0)), fbm4(p+vec2(6.2)) ); }
vec2 fbm6_2(vec2 p){ return vec2( fbm6(p+vec2(9.2)), fbm6(p+vec2(5.7)) ); }

float func(vec2 q, out vec2 o, out vec2 n){
    q += 0.05*sin(vec2(0.11,0.13)*iTime + length(q)*4.0);
    q *= 0.37 + 0.2*cos(0.05*iTime);
    o = 0.5 + 0.5*fbm4_2(q);
    o += 0.2*sin(vec2(0.13,0.11)*iTime*length(o));
    n = fbm6_2(4.0*o);
    vec2 p = q + 2.0*n + 1.0;
    float f = 0.5 + 0.5*fbm4(2.0*p);
    f = mix(f, f*f*f*3.5, f*abs(n.x));
    f *= 1.0-0.5*pow(0.5+0.5*sin(8.0*p.x)*sin(8.0*p.y), 8.0);
    return f;
}
float funcs(vec2 q){ vec2 t1,t2; return func(q,t1,t2); }

// ---------------- Our glue around the fbm field -------------------
struct Field{ float f; vec2 g; };
Field fbmField(vec2 p){
    float e = 0.001;
    float v = funcs(p);
    float gx = funcs(p+vec2(e,0.0))-v;
    float gy = funcs(p+vec2(0.0,e))-v;
    return Field(v, vec2(gx,gy)/e);
}

// ---------------- Metaball / iridescence code ---------------------
float metaball(vec2 uv, vec2 c, float r){ float d=length(uv-c); return r/(d*d+0.01); }

float createSurfaces(vec2 uv,float t){
    float tt = t*0.13;
    float b1 = metaball(uv, vec2(0.3+sin(tt)*0.2, 0.4+cos(tt*1.2)*0.15), 0.08);
    float b2 = metaball(uv, vec2(0.7+cos(tt*0.8)*0.25, 0.6+sin(tt*1.5)*0.2), 0.12);
    float b3 = metaball(uv, vec2(0.5+sin(tt*1.3)*0.3, 0.3+cos(tt*0.9)*0.25), 0.10);
    float b4 = metaball(uv, vec2(0.4+cos(tt*1.1)*0.2, 0.7+sin(tt*0.7)*0.18), 0.09);
    return b1+b2+b3+b4;
}

vec2 getNormal(vec2 uv,float t){
    float eps=0.002;
    float c = createSurfaces(uv,t);
    float dx= createSurfaces(uv+vec2(eps,0.0),t);
    float dy= createSurfaces(uv+vec2(0.0,eps),t);
    return normalize(vec2(c-dx, c-dy));
}

// Simple 6-stop rainbow
vec3 iridescentPalette(float x){
    x = mod(x,6.0);
    if(x<1.0) return mix(vec3(1.0,0.0,0.5), vec3(1.0,0.3,0.0),x);
    if(x<2.0) return mix(vec3(1.0,0.3,0.0), vec3(1.0,1.0,0.0),x-1.0);
    if(x<3.0) return mix(vec3(1.0,1.0,0.0), vec3(0.0,1.0,0.5),x-2.0);
    if(x<4.0) return mix(vec3(0.0,1.0,0.5), vec3(0.0,0.5,1.0),x-3.0);
    if(x<5.0) return mix(vec3(0.0,0.5,1.0), vec3(0.5,0.0,1.0),x-4.0);
    return             mix(vec3(0.5,0.0,1.0), vec3(1.0,0.0,0.5),x-5.0);
}
vec3 iridescent(float ang,float inten,vec2 uv){
    vec3 c = iridescentPalette(ang*3.0+u_time*0.5);
    float var = sin(uv.x*10.0+u_time)*sin(uv.y*8.0+u_time*1.3);
    return (c+var*0.1)*inten;
}
float volumetric(vec2 uv,float s){
    float d = length(uv-0.5);
    float v = smoothstep(10.1,20.0,s)*(2.0-d*1.8);
    return v;
}

// ------------------------------ main() -----------------------------
void main(){
    vec2 uv = vTexCoord;
    float t  = u_time;

    // fbm backdrop & UV warp
    Field fld = fbmField(uv*3.0);
    vec2 wUV  = uv + 0.03*fld.g;

    // metaball density in warped space
    float surf = createSurfaces(wUV,t);
    float inten= smoothstep(0.3,1.5,surf);

    // lighting vectors
    vec2 n2d  = getNormal(wUV,t);
    float ang = atan(n2d.y,n2d.x)+3.14159;

    // colour blend
    vec3 nebula = mix(vec3(0.1,0.05,0.2), vec3(0.7,0.3,0.9), fld.f);
    vec3 blob   = iridescent(ang,inten,wUV);
    vec3 col    = mix(nebula, blob, inten);

    // extra shading
    vec3 lightDir = normalize(vec3(1.0,1.0,0.5));
    float ldot = dot(normalize(vec3(n2d,1.0)), lightDir);
    col *= 0.5+0.5*ldot;
    col += pow(max(ldot,0.0),16.0)*0.5;            // specular
    col *= volumetric(uv,surf)+0.1;
    float edge = 1.0-smoothstep(0.3,0.8,surf);
    col += edge*vec3(0.8,0.9,1.0)*0.3;

    gl_FragColor = vec4(pow(col, vec3(0.9))*1.5, 1.0);
}
`;

// ---------------------------------------------------------------------------
// p5.js scaffold
// ---------------------------------------------------------------------------
function setup(){
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
  myShader = createShader(vertSource, fragSource);
}

function draw(){
  shader(myShader);
  myShader.setUniform('u_time', millis()*0.00085);
  myShader.setUniform('u_resolution', [width, height]);
  rect(-width/2, -height/2, width, height);
}

function windowResized(){ resizeCanvas(windowWidth, windowHeight); }

